package render

import (
	"bufio"
	"fmt"
	"net/netip"
	"sort"
	"strings"

	"github.com/martincvitic19/custos-marginis/custos/internal/config"
	"github.com/martincvitic19/custos-marginis/custos/internal/state"
)

// File is one generated file: path and content. Mode and group are set by
// the writer.
type File struct {
	Path    string
	Content string
	Mode    uint32
	// Group, if set, owns the file (e.g. systemd-network for key files).
	Group string
}

// NetworkdDir is where generated networkd files go. /run has priority over
// /usr/lib (the image's static files), and drop-ins (*.network.d) add
// sections to them.
const NetworkdDir = "/run/systemd/network"

// Routing table for traffic from VPN peers when they exit through Mullvad.
const VPNTable = 100

// Leases renders one drop-in per VLAN with the DHCP reservations of the
// known devices on it (VLANs without devices get none).
func Leases(c *config.Config, s *state.State) []File {
	byVLAN := map[int][]config.Device{}
	for _, d := range c.Devices {
		byVLAN[d.VLAN] = append(byVLAN[d.VLAN], d)
	}
	var out []File
	for _, v := range c.Network.VLANs {
		devs := byVLAN[v.ID]
		if len(devs) == 0 {
			continue
		}
		sort.Slice(devs, func(i, j int) bool { return devs[i].MAC < devs[j].MAC })
		var b strings.Builder
		b.WriteString("# Generated by custos-apply: DHCP reservations for known devices.\n")
		for _, d := range devs {
			fmt.Fprintf(&b, "\n# %s (%s)\n[DHCPServerStaticLease]\nMACAddress=%s\nAddress=%s\n",
				d.Name, d.Role, d.MAC, s.Leases[state.LeaseKey(d.MAC, d.VLAN)])
		}
		name := fmt.Sprintf("05-custos-%s.network.d/50-custos-leases.conf", c.VLANIf(v.ID))
		out = append(out, File{Path: NetworkdDir + "/" + name, Content: b.String(), Mode: 0644})
	}
	return out
}

// Mullvad is the part of a Mullvad WireGuard configuration file that
// Custos uses (wg-quick format, as downloaded from the Mullvad account).
type Mullvad struct {
	PrivateKey string
	Address    netip.Prefix // IPv4 only: clients get no IPv6
	PublicKey  string
	Endpoint   string
}

// ParseMullvad reads a wg-quick style file. Unknown keys are ignored; the
// ones Custos needs are validated so they can go into networkd files.
func ParseMullvad(data string) (*Mullvad, error) {
	m := &Mullvad{}
	sec := ""
	sc := bufio.NewScanner(strings.NewReader(data))
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" || line[0] == '#' {
			continue
		}
		if strings.HasPrefix(line, "[") {
			sec = strings.ToLower(strings.Trim(line, "[]"))
			continue
		}
		k, v, ok := strings.Cut(line, "=")
		if !ok {
			continue
		}
		k, v = strings.ToLower(strings.TrimSpace(k)), strings.TrimSpace(v)
		switch sec + "." + k {
		case "interface.privatekey":
			m.PrivateKey = v
		case "interface.address":
			for _, a := range strings.Split(v, ",") {
				p, err := netip.ParsePrefix(strings.TrimSpace(a))
				if err == nil && p.Addr().Is4() {
					m.Address = p
				}
			}
		case "peer.publickey":
			m.PublicKey = v
		case "peer.endpoint":
			m.Endpoint = v
		}
	}
	key := func(s string) bool { return len(s) == 44 && strings.HasSuffix(s, "=") && !strings.ContainsAny(s, " \"'\n") }
	if !key(m.PrivateKey) || !key(m.PublicKey) {
		return nil, fmt.Errorf("mullvad.conf: missing or invalid PrivateKey/PublicKey")
	}
	if !m.Address.IsValid() {
		return nil, fmt.Errorf("mullvad.conf: no IPv4 Address")
	}
	if _, err := netip.ParseAddrPort(m.Endpoint); err != nil {
		return nil, fmt.Errorf("mullvad.conf: Endpoint must be IPv4:port (%v)", err)
	}
	return m, nil
}

// VPN renders wg0 (server) and, when a Mullvad configuration exists,
// wg-mullvad (client) with the policy routing that sends peer traffic to
// Mullvad. keyDir holds wg0.key and mullvad.key (readable by
// systemd-network).
func VPN(c *config.Config, m *Mullvad, keyDir string) []File {
	if !c.VPN.Enabled {
		return nil
	}
	subnet := netip.MustParsePrefix(c.VPN.Subnet)
	router := netip.PrefixFrom(subnet.Addr().Next(), subnet.Bits())
	var nd strings.Builder
	fmt.Fprintf(&nd, `# Generated by custos-apply: WireGuard server for devices away from home.
[NetDev]
Name=wg0
Kind=wireguard

[WireGuard]
PrivateKeyFile=%s/wg0.key
ListenPort=%d
`, keyDir, c.VPN.Port)
	peers := append([]config.Peer(nil), c.VPN.Peers...)
	sort.Slice(peers, func(i, j int) bool { return peers[i].Address < peers[j].Address })
	for _, p := range peers {
		fmt.Fprintf(&nd, "\n# %s (%s)\n[WireGuardPeer]\nPublicKey=%s\nAllowedIPs=%s/32\n", p.Name, p.Role, p.PublicKey, p.Address)
	}
	var nw strings.Builder
	fmt.Fprintf(&nw, `# Generated by custos-apply.
[Match]
Name=wg0

[Link]
RequiredForOnline=no

[Network]
Address=%s
`, router)
	if c.VPN.Exit == "mullvad" {
		fmt.Fprintf(&nw, `
# Traffic arriving from the peers uses table %[1]d, whose only default
# route is wg-mullvad. With no Mullvad tunnel the table is empty and the
# firewall's kill switch drops the traffic (it never falls back to wan).
# Matched by incoming interface, not by source address: the router's own
# replies to the peers (DNS, UI) come from %[2]s too and must stay in the
# main table.
[RoutingPolicyRule]
IncomingInterface=wg0
Table=%[1]d
Priority=100
`, VPNTable, subnet.Addr().Next())
	}
	out := []File{
		{Path: NetworkdDir + "/30-custos-wg0.netdev", Content: nd.String(), Mode: 0640, Group: "systemd-network"},
		{Path: NetworkdDir + "/30-custos-wg0.network", Content: nw.String(), Mode: 0644},
	}
	if c.VPN.Exit == "mullvad" && m != nil {
		out = append(out,
			File{Path: NetworkdDir + "/31-custos-wg-mullvad.netdev", Mode: 0640, Group: "systemd-network", Content: fmt.Sprintf(`# Generated by custos-apply from /data/custos/wg/mullvad.conf.
[NetDev]
Name=wg-mullvad
Kind=wireguard

[WireGuard]
PrivateKeyFile=%s/mullvad.key
# Routes are set in the .network file (table %d only, never main).
RouteTable=off

[WireGuardPeer]
PublicKey=%s
Endpoint=%s
AllowedIPs=0.0.0.0/0
PersistentKeepalive=25
`, keyDir, VPNTable, m.PublicKey, m.Endpoint)},
			File{Path: NetworkdDir + "/31-custos-wg-mullvad.network", Mode: 0644, Content: fmt.Sprintf(`# Generated by custos-apply. The home LAN never uses this tunnel: only
# table %[1]d (VPN peers) has a route through it.
[Match]
Name=wg-mullvad

[Link]
RequiredForOnline=no

[Network]
Address=%[2]s

[Route]
Destination=0.0.0.0/0
Table=%[1]d
`, VPNTable, m.Address)})
	}
	return out
}

// WiFiIf returns the interface name hostapd uses for SSID i.
func WiFiIf(i int) string {
	if i == 0 {
		return "wlan0"
	}
	return fmt.Sprintf("wlan0-%d", i)
}

// HostapdPath is the generated configuration custos-hostapd.service runs.
const HostapdPath = "/run/custos/hostapd.conf"

// WiFi renders hostapd.conf and one networkd file per SSID that bridges the
// interface into its VLAN. baseMAC is the radio's address (for the extra
// BSSIDs). Nothing is rendered without a radio or with Wi-Fi disabled.
func WiFi(c *config.Config, sec *state.Secrets, baseMAC string) []File {
	if !c.WiFi.Enabled || baseMAC == "" || len(c.WiFi.SSIDs) == 0 {
		return nil
	}
	mode := "a"
	if c.WiFi.Band == "g" {
		mode = "g"
	}
	var h strings.Builder
	fmt.Fprintf(&h, `# Generated by custos-apply from /data/custos/custos.json. Do not edit.
# Compex WLE900VX (QCA9880, ath10k). One BSS per SSID; each is bridged into
# its VLAN by systemd-networkd (06-custos-wlan*.network).
driver=nl80211
ctrl_interface=/run/hostapd
ctrl_interface_group=0
country_code=%s
ieee80211d=1
hw_mode=%s
channel=%d
ieee80211n=1
wmm_enabled=1
ht_capab=[SHORT-GI-20]
`, c.WiFi.Country, mode, c.WiFi.Channel)
	if mode == "a" {
		h.WriteString("ieee80211h=1\nieee80211ac=1\nvht_oper_chwidth=0\n")
	}
	var out []File
	for i, s := range c.WiFi.SSIDs {
		ifn := WiFiIf(i)
		if i == 0 {
			fmt.Fprintf(&h, "\ninterface=%s\n", ifn)
		} else {
			fmt.Fprintf(&h, "\nbss=%s\nbssid=%s\n", ifn, bssid(baseMAC, i))
		}
		isolate := 0
		if s.VLAN != c.Network.AdminVLAN {
			isolate = 1 // children/guests do not see each other's devices
		}
		fmt.Fprintf(&h, `bridge=%s
ssid=%s
utf8_ssid=1
ignore_broadcast_ssid=0
ap_isolate=%d
auth_algs=1
wpa=2
# WPA3-SAE and WPA2 (SHA-256 PSK), management frame protection required.
wpa_key_mgmt=SAE WPA-PSK-SHA256
rsn_pairwise=CCMP
ieee80211w=2
sae_require_mfp=1
sae_pwe=2
wpa_passphrase=%s
`, c.Network.Bridge, s.Name, isolate, sec.WiFi[s.Name])
		out = append(out, File{Path: fmt.Sprintf("%s/06-custos-%s.network", NetworkdDir, ifn), Mode: 0644, Content: fmt.Sprintf(`# Generated by custos-apply: SSID %q -> VLAN %d.
[Match]
Name=%s

[Link]
RequiredForOnline=no

[Network]
Bridge=%s
LinkLocalAddressing=no
IPv6AcceptRA=no
ConfigureWithoutCarrier=yes

[BridgeVLAN]
PVID=%d
EgressUntagged=%d
`, s.Name, s.VLAN, ifn, c.Network.Bridge, s.VLAN, s.VLAN)})
	}
	out = append(out, File{Path: HostapdPath, Content: h.String(), Mode: 0600})
	return out
}

// bssid derives a locally administered address for BSS i from the radio
// MAC (same scheme as OpenWrt: set the LA bit, change the last byte).
func bssid(base string, i int) string {
	var b [6]byte
	fmt.Sscanf(base, "%x:%x:%x:%x:%x:%x", &b[0], &b[1], &b[2], &b[3], &b[4], &b[5])
	b[0] |= 0x02
	b[5] = byte(int(b[5]) + i)
	return fmt.Sprintf("%02x:%02x:%02x:%02x:%02x:%02x", b[0], b[1], b[2], b[3], b[4], b[5])
}
